CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,uid INTEGER NOT NULL, expires INTEGER NOT NULL,sso INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY, username TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(k TEXT PRIMARY KEY,n INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS invoices(id TEXT PRIMARY KEY,uid INTEGER NOT NULL,plan TEXT NOT NULL,term TEXT NOT NULL,runtime TEXT NOT NULL,coin TEXT NOT NULL,units INTEGER NOT NULL,created INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'waiting',tx TEXT UNIQUE,server TEXT,sid INTEGER,expires INTEGER, UNIQUE(coin,units));
CREATE UNIQUE INDEX IF NOT EXISTS one_waiting ON invoices(uid) WHERE status='waiting';
CREATE UNIQUE INDEX IF NOT EXISTS web_free_slot ON invoices(uid) WHERE plan='Free';
